import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { motion, AnimatePresence } from 'framer-motion';
import {
    UserPlus, Users, Search, Filter, Eye, Edit2,
    Trash2, Key, UserCheck, UserX, Mail, Phone,
    Briefcase, DollarSign, Percent, EyeOff
} from 'lucide-react';
import toast from 'react-hot-toast';
import salesRepService from '../../services/salesRepService';
import DataTable from '../../components/datadisplay/DataTable';
import StatusBadge from '../../components/datadisplay/StatusBadge';
import ConfirmDialog from '../../components/feedback/ConfirmDialog';
import SalesRepFormModal from './SalesRepFormModal';
import SalesRepDetailsModal from './SalesRepDetailsModal';
import PasswordResetModal from './PasswordResetModal';

const SalesRepManagement = () => {
    const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
    const [editingRep, setEditingRep] = useState(null);
    const [viewingRep, setViewingRep] = useState(null);
    const [resetPasswordRep, setResetPasswordRep] = useState(null);
    const [toggleConfirm, setToggleConfirm] = useState(null);
    const [filters, setFilters] = useState({ search: '', isActive: undefined });
    const [credentialsModal, setCredentialsModal] = useState(null);

    const queryClient = useQueryClient();

    const { data: salesReps, isLoading } = useQuery({
        queryKey: ['sales-reps', filters],
        queryFn: () => salesRepService.getAllSalesReps(filters)
    });

    const toggleMutation = useMutation({
        mutationFn: ({ id, action }) => salesRepService.toggleActive(id, action),
        onSuccess: (data) => {
            toast.success(data.message);
            queryClient.invalidateQueries(['sales-reps']);
            setToggleConfirm(null);
        },
        onError: (error) => {
            toast.error(error.response?.data?.message || 'Failed to update status');
        }
    });

    const columns = [
        {
            key: 'name',
            label: 'Sales Representative',
            sortable: true,
            render: (row) => (
                <div className="flex items-center gap-3">
                    <div className="h-10 w-10 rounded-full bg-indigo-100 dark:bg-indigo-900/30 flex items-center justify-center">
                        <span className="text-sm font-bold text-indigo-600">
                            {row.firstName?.[0]}{row.lastName?.[0]}
                        </span>
                    </div>
                    <div>
                        <p className="font-medium text-gray-900 dark:text-white">
                            {row.firstName} {row.lastName}
                        </p>
                        <div className="flex items-center gap-1 text-xs text-gray-500">
                            <Mail className="h-3 w-3" />
                            {row.email}
                        </div>
                    </div>
                </div>
            )
        },
        {
            key: 'phone',
            label: 'Phone',
            render: (row) => (
                <span className="text-sm text-gray-500">
                    {row.phone || 'N/A'}
                </span>
            )
        },
        {
            key: 'commission',
            label: 'Commission',
            render: (row) => (
                <div className="space-y-1">
                    {row.commission ? (
                        <>
                            <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-teal-100 text-teal-800 dark:bg-teal-900/30 dark:text-teal-400">
                                {row.commission.structure.replace(/_/g, ' ')}
                            </span>
                            {row.commission.baseSalary > 0 && (
                                <div className="flex items-center gap-1 text-xs text-gray-500">
                                    <DollarSign className="h-3 w-3" />
                                    ${row.commission.baseSalary}/mo
                                </div>
                            )}
                            {row.commission.commissionPercentage > 0 && (
                                <div className="flex items-center gap-1 text-xs text-gray-500">
                                    <Percent className="h-3 w-3" />
                                    {row.commission.commissionPercentage}%
                                </div>
                            )}
                        </>
                    ) : (
                        <span className="text-xs text-gray-400">Not set</span>
                    )}
                </div>
            )
        },
        {
            key: 'stats',
            label: 'Performance',
            render: (row) => (
                <div className="space-y-1">
                    <div className="text-sm font-medium text-gray-900 dark:text-white">
                        {row.stats?.totalOrders || 0} orders
                    </div>
                    <div className="text-xs text-gray-500">
                        {row.stats?.completedOrders || 0} completed
                    </div>
                    <div className="text-xs font-medium text-emerald-600">
                        ${(row.stats?.totalRevenue || 0).toLocaleString()}
                    </div>
                </div>
            )
        },
        {
            key: 'status',
            label: 'Status',
            render: (row) => (
                <StatusBadge
                    status={row.isActive ? 'active' : 'inactive'}
                    label={row.isActive ? 'Active' : 'Inactive'}
                />
            )
        },
        {
            key: 'actions',
            label: 'Actions',
            render: (row) => (
                <div className="flex items-center gap-1">
                    <button
                        onClick={() => setViewingRep(row)}
                        className="p-2 text-gray-400 hover:text-indigo-600 dark:hover:text-indigo-400 transition-colors"
                        title="View Details"
                    >
                        <Eye className="h-4 w-4" />
                    </button>
                    <button
                        onClick={() => {
                            setEditingRep(row);
                            setIsCreateModalOpen(true);
                        }}
                        className="p-2 text-gray-400 hover:text-indigo-600 dark:hover:text-indigo-400 transition-colors"
                        title="Edit"
                    >
                        <Edit2 className="h-4 w-4" />
                    </button>
                    <button
                        onClick={() => setResetPasswordRep(row)}
                        className="p-2 text-gray-400 hover:text-amber-600 dark:hover:text-amber-400 transition-colors"
                        title="Reset Password"
                    >
                        <Key className="h-4 w-4" />
                    </button>
                    <button
                        onClick={() => setToggleConfirm({
                            id: row.id,
                            action: row.isActive ? 'deactivate' : 'reactivate',
                            name: `${row.firstName} ${row.lastName}`
                        })}
                        className="p-2 text-gray-400 hover:text-rose-600 dark:hover:text-rose-400 transition-colors"
                        title={row.isActive ? 'Deactivate' : 'Reactivate'}
                    >
                        {row.isActive ? <UserX className="h-4 w-4" /> : <UserCheck className="h-4 w-4" />}
                    </button>
                </div>
            )
        }
    ];

    const handleCreateSuccess = (data) => {
        queryClient.invalidateQueries(['sales-reps']);
        setIsCreateModalOpen(false);
        setEditingRep(null);

        // Show credentials modal with generated password
        if (data.generatedPassword) {
            setCredentialsModal({
                email: data.user.email,
                password: data.generatedPassword,
                name: `${data.user.firstName} ${data.user.lastName}`
            });
        }
    };

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
                <div>
                    <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
                        Sales Representatives
                    </h1>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">
                        Manage your sales team, commissions, and performance
                    </p>
                </div>

                <motion.button
                    whileHover={{ scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}
                    onClick={() => {
                        setEditingRep(null);
                        setIsCreateModalOpen(true);
                    }}
                    className="flex items-center gap-2 px-4 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg font-medium transition-colors"
                >
                    <UserPlus className="h-5 w-5" />
                    Add Sales Rep
                </motion.button>
            </div>

            {/* Quick Stats */}
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                <QuickStatCard
                    icon={Users}
                    label="Total Reps"
                    value={salesReps?.length || 0}
                    color="indigo"
                />
                <QuickStatCard
                    icon={UserCheck}
                    label="Active Reps"
                    value={salesReps?.filter(r => r.isActive).length || 0}
                    color="emerald"
                />
                <QuickStatCard
                    icon={Briefcase}
                    label="Avg Orders/Rep"
                    value={salesReps?.length > 0
                        ? Math.round(salesReps.reduce((sum, r) => sum + (r.stats?.totalOrders || 0), 0) / salesReps.length)
                        : 0}
                    color="amber"
                />
            </div>

            {/* Table */}
            <DataTable
                columns={columns}
                data={salesReps || []}
                loading={isLoading}
                emptyMessage="No sales representatives found. Add your first rep!"
                onSearch={(search) => setFilters(prev => ({ ...prev, search }))}
            />

            {/* Create/Edit Modal */}
            <SalesRepFormModal
                isOpen={isCreateModalOpen}
                onClose={() => {
                    setIsCreateModalOpen(false);
                    setEditingRep(null);
                }}
                editingRep={editingRep}
                onSuccess={handleCreateSuccess}
            />

            {/* View Details Modal */}
            <SalesRepDetailsModal
                isOpen={!!viewingRep}
                onClose={() => setViewingRep(null)}
                salesRep={viewingRep}
            />

            {/* Password Reset Modal */}
            <PasswordResetModal
                isOpen={!!resetPasswordRep}
                onClose={() => setResetPasswordRep(null)}
                salesRep={resetPasswordRep}
            />

            {/* Credentials Modal (shown after creation) */}
            <CredentialsModal
                isOpen={!!credentialsModal}
                onClose={() => setCredentialsModal(null)}
                credentials={credentialsModal}
            />

            {/* Toggle Active Confirm */}
            <ConfirmDialog
                isOpen={!!toggleConfirm}
                onClose={() => setToggleConfirm(null)}
                onConfirm={() => toggleMutation.mutate(toggleConfirm)}
                title={toggleConfirm?.action === 'deactivate' ? 'Deactivate Sales Rep' : 'Reactivate Sales Rep'}
                message={`Are you sure you want to ${toggleConfirm?.action} "${toggleConfirm?.name}"?`}
                confirmText={toggleConfirm?.action === 'deactivate' ? 'Deactivate' : 'Reactivate'}
                variant={toggleConfirm?.action === 'deactivate' ? 'danger' : 'primary'}
                loading={toggleMutation.isLoading}
            />
        </div>
    );
};

const QuickStatCard = ({ icon: Icon, label, value, color }) => {
    const colorVariants = {
        indigo: 'bg-indigo-100 text-indigo-600 dark:bg-indigo-900/30 dark:text-indigo-400',
        emerald: 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400',
        amber: 'bg-amber-100 text-amber-600 dark:bg-amber-900/30 dark:text-amber-400',
    };

    return (
        <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-white dark:bg-gray-800 rounded-xl p-4 shadow-sm border border-gray-200 dark:border-gray-700"
        >
            <div className="flex items-center gap-3">
                <div className={`p-2 rounded-lg ${colorVariants[color]}`}>
                    <Icon className="h-5 w-5" />
                </div>
                <div>
                    <p className="text-sm text-gray-500 dark:text-gray-400">{label}</p>
                    <p className="text-xl font-bold text-gray-900 dark:text-white">{value}</p>
                </div>
            </div>
        </motion.div>
    );
};

export default SalesRepManagement;
